function() {
  try {
    // 1. Get the raw string from localStorage
    var consentRaw = localStorage.getItem('consent_mode');

    // 2. If it doesn't exist, return undefined or a default
    if (!consentRaw) return undefined;

    // 3. Parse the JSON string into an object
    var consentObj = JSON.parse(consentRaw);

    // 4. Return the analytics_storage value 
    return consentObj.analytics_storage || undefined;

  } catch (e) {
    // Fallback in case of parsing errors
    return undefined;
  }
}
